const listRotationProposals = `-- name: ListRotationProposals :many
SELECT rp.public_id, rps.code AS status, rp.quorum_percent, rp.eligible_members,
       rp.opens_at, rp.closes_at, rp.closed_at, rp.created_at,
       (count(rv.id) FILTER (WHERE vc.code = 'for'))::int AS for_count,
       (count(rv.id) FILTER (WHERE vc.code = 'against'))::int AS against_count,
       (count(rv.id) FILTER (WHERE vc.code = 'abstain'))::int AS abstain_count,
       count(rv.id)::int AS total_count
FROM rotation_proposals rp
JOIN rotation_proposal_statuses rps ON rps.id = rp.status_id
LEFT JOIN rotation_votes rv ON rv.proposal_id = rp.id
LEFT JOIN vote_choices vc ON vc.id = rv.choice_id
WHERE rp.group_id = $1
  AND rp.cycle_id = (SELECT rc.id FROM rotation_cycles rc
                     WHERE rc.public_id = $2 AND rc.group_id = $1)
GROUP BY rp.public_id, rps.code, rp.quorum_percent, rp.eligible_members,
         rp.opens_at, rp.closes_at, rp.closed_at, rp.created_at
ORDER BY rp.created_at DESC
LIMIT $3
`

type ListRotationProposalsParams struct {
	GroupID       int64
	CyclePublicID uuid.UUID
	RowLimit      int32
}

type ListRotationProposalsRow struct {
	PublicID        uuid.UUID
	Status          string
	QuorumPercent   int16
	EligibleMembers int16
	OpensAt         time.Time
	ClosesAt        time.Time
	ClosedAt        *time.Time
	CreatedAt       time.Time
	ForCount        int32
	AgainstCount    int32
	AbstainCount    int32
	TotalCount      int32
}

func (q *Queries) ListRotationProposals(ctx context.Context, arg ListRotationProposalsParams) ([]ListRotationProposalsRow, error) {
	rows, err := q.db.Query(ctx, listRotationProposals, arg.GroupID, arg.CyclePublicID, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListRotationProposalsRow
	for rows.Next() {
		var i ListRotationProposalsRow
		if err := rows.Scan(
			&i.PublicID,
			&i.Status,
			&i.QuorumPercent,
			&i.EligibleMembers,
			&i.OpensAt,
			&i.ClosesAt,
			&i.ClosedAt,
			&i.CreatedAt,
			&i.ForCount,
			&i.AgainstCount,
			&i.AbstainCount,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

