const tallyRotationVotes = `-- name: TallyRotationVotes :one
SELECT count(*) FILTER (WHERE vc.code = 'for')::int AS for_count,
       count(*) FILTER (WHERE vc.code = 'against')::int AS against_count,
       count(*) FILTER (WHERE vc.code = 'abstain')::int AS abstain_count,
       count(*)::int AS total_count
FROM rotation_votes rv
JOIN vote_choices vc ON vc.id = rv.choice_id
WHERE rv.proposal_id = $1
`

type TallyRotationVotesRow struct {
	ForCount     int32
	AgainstCount int32
	AbstainCount int32
	TotalCount   int32
}

func (q *Queries) TallyRotationVotes(ctx context.Context, proposalID int64) (TallyRotationVotesRow, error) {
	row := q.db.QueryRow(ctx, tallyRotationVotes, proposalID)
	var i TallyRotationVotesRow
	err := row.Scan(
		&i.ForCount,
		&i.AgainstCount,
		&i.AbstainCount,
		&i.TotalCount,
	)
	return i, err
}

const updateRotationCycleStatus = `-- name: UpdateRotationCycleStatus :execrows
UPDATE rotation_cycles rc
SET status_id = (SELECT rcs.id FROM rotation_cycle_statuses rcs WHERE rcs.code = $1),
    completed_at = CASE WHEN $1::text = 'completed' THEN now() ELSE rc.completed_at END
WHERE rc.id = $2 AND rc.group_id = $3
  AND status_id = (SELECT rcs.id FROM rotation_cycle_statuses rcs WHERE rcs.code = $4)
`

type UpdateRotationCycleStatusParams struct {
	Status         string
	CycleID        int64
	GroupID        int64
	ExpectedStatus string
}

func (q *Queries) UpdateRotationCycleStatus(ctx context.Context, arg UpdateRotationCycleStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateRotationCycleStatus,
		arg.Status,
		arg.CycleID,
		arg.GroupID,
		arg.ExpectedStatus,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertRotationVote = `-- name: UpsertRotationVote :exec
INSERT INTO rotation_votes (group_id, proposal_id, member_id, choice_id)
VALUES (
    $1, $2, $3,
    (SELECT vc.id FROM vote_choices vc WHERE vc.code = $4)
)
ON CONFLICT (proposal_id, member_id) DO UPDATE
SET choice_id = EXCLUDED.choice_id, cast_at = now()
`

type UpsertRotationVoteParams struct {
	GroupID    int64
	ProposalID int64
	MemberID   int64
	Choice     string
}

func (q *Queries) UpsertRotationVote(ctx context.Context, arg UpsertRotationVoteParams) error {
	_, err := q.db.Exec(ctx, upsertRotationVote,
		arg.GroupID,
		arg.ProposalID,
		arg.MemberID,
		arg.Choice,
	)
	return err
}
